#!/bin/sh
set -eu

crate_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
repo_dir=$(CDPATH= cd -- "$crate_dir/../.." && pwd)
formal_dir="$repo_dir/formal/dclutch-semantics"
accepted="$crate_dir/src/generated_price_gate_v1.rs"
temporary=$(mktemp "${TMPDIR:-/tmp}/dclutch-product-price-gate-v1.XXXXXX")
trap 'rm -f "$temporary"' EXIT HUP INT TERM

(
  cd "$formal_dir"
  lake build DClutchSemantics.LiabilityBasisV2PriceGateAbi
  lake env lean --run EmitProductPriceGateV1AbiRust.lean > "$temporary"
)

test "$(sed -n '1p' "$temporary")" = \
  '// @generated by formal/dclutch-semantics/EmitProductPriceGateV1AbiRust.lean; do not edit.'

# Pinned by value. This file and the kernel's `generated_price_gate.rs` are two
# emissions of ONE Lean ABI owner -- `PriceGate.PhysicalAbi` -- rather than two
# hand-kept copies, because the founding gate has to decode `DCLTPGT1` from the
# crate Core links and the kernel is a dev-dependency that must stay one under
# `O-005`. `the_two_price_gate_emissions_agree` is the Rust-side check that the
# two destinations still say the same thing; these greps are the check that
# neither drifted from the specification that authored both.
grep -q '^pub const PRICE_GATE_REQUEST_BYTES_V1: usize = 320;$' "$temporary"
grep -q '^pub const PRICE_GATE_SCHEMA_VERSION_V1: u16 = 1;$' "$temporary"
grep -q '^pub const PRICE_GATE_PROFILE_V1: u16 = 1;$' "$temporary"

# Capacity 10 is affine Caratheodory, not an arbitrary cap: a point in the
# convex hull of a `width`-dimensional simplex needs at most `width` atoms to
# witness it. Widening it silently would widen what the no-arbitrage proof has
# to cover.
grep -q '^pub const PRICE_GATE_MAX_WIDTH_V1: usize = 10;$' "$temporary"
grep -q '^pub const PRICE_GATE_MAX_ATOMS_V1: usize = 10;$' "$temporary"

# The reserved span, named explicitly for the same reason the basis record's
# two spans are: it is what lets a decoder refuse rather than misread a record
# written by a newer author.
grep -q '^pub const PRICE_GATE_RESERVED_OFFSET_V1: usize = 27;$' "$temporary"
grep -q '^pub const PRICE_GATE_RESERVED_BYTES_V1: usize = 13;$' "$temporary"

# The four parallel arrays, pinned where they start. These are the offsets a
# hull check reads every atom through.
grep -q '^pub const PRICE_GATE_PRICES_OFFSET_V1: usize = 40;$' "$temporary"
grep -q '^pub const PRICE_GATE_WEIGHTS_OFFSET_V1: usize = 120;$' "$temporary"
grep -q '^pub const PRICE_GATE_NUMERATORS_OFFSET_V1: usize = 200;$' "$temporary"
grep -q '^pub const PRICE_GATE_DENOMINATORS_OFFSET_V1: usize = 280;$' "$temporary"

# The exempt degree is 1, and `exempt_degree_below_spline_interval` is the proof
# that the spline family's interval starting at 2 makes a certificate mandatory
# for the whole of it with no runtime degree comparison. Raising this to 2 would
# silently exempt curvature from its own gate.
grep -q '^pub const PRICE_GATE_EXEMPT_DEGREE_V1: u8 = 1;$' "$temporary"

rustfmt --edition 2024 "$temporary"
cmp "$temporary" "$accepted"
